import{_ as a,o as l,c as s,ah as e}from"./chunks/framework.CPHJ30oF.js";const o=JSON.parse('{"title":"13-Docker-Swarm-从零搭建生产可用的高可用容器集群","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"1. Swarm 是什么？","slug":"_1-swarm-是什么","link":"#_1-swarm-是什么","children":[]},{"level":2,"title":"2. Swarm 基本概念","slug":"_2-swarm-基本概念","link":"#_2-swarm-基本概念","children":[]},{"level":2,"title":"3. 从零搭建 Swarm","slug":"_3-从零搭建-swarm","link":"#_3-从零搭建-swarm","children":[{"level":3,"title":"初始化 Swarm","slug":"初始化-swarm","link":"#初始化-swarm","children":[]},{"level":3,"title":"加入工作节点","slug":"加入工作节点","link":"#加入工作节点","children":[]},{"level":3,"title":"查看节点状态","slug":"查看节点状态","link":"#查看节点状态","children":[]}]},{"level":2,"title":"4. 部署服务","slug":"_4-部署服务","link":"#_4-部署服务","children":[]},{"level":2,"title":"5. 生产实践建议","slug":"_5-生产实践建议","link":"#_5-生产实践建议","children":[{"level":3,"title":"5.1 节点角色规划","slug":"_5-1-节点角色规划","link":"#_5-1-节点角色规划","children":[]},{"level":3,"title":"5.2 网络与存储","slug":"_5-2-网络与存储","link":"#_5-2-网络与存储","children":[]},{"level":3,"title":"5.3 健康检查与更新策略","slug":"_5-3-健康检查与更新策略","link":"#_5-3-健康检查与更新策略","children":[]},{"level":3,"title":"5.4 监控与告警","slug":"_5-4-监控与告警","link":"#_5-4-监控与告警","children":[]}]},{"level":2,"title":"6. 什么时候选择 Swarm","slug":"_6-什么时候选择-swarm","link":"#_6-什么时候选择-swarm","children":[]},{"level":2,"title":"7. 常见误区","slug":"_7-常见误区","link":"#_7-常见误区","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/13-Docker-Swarm-从零搭建生产可用的高可用容器集群.md","filePath":"docker/13-Docker-Swarm-从零搭建生产可用的高可用容器集群.md"}'),r={name:"docker/13-Docker-Swarm-从零搭建生产可用的高可用容器集群.md"};function h(t,i,n,k,d,p){return l(),s("div",null,[...i[0]||(i[0]=[e('<h1 id="_13-docker-swarm-从零搭建生产可用的高可用容器集群" tabindex="-1">13-Docker-Swarm-从零搭建生产可用的高可用容器集群 <a class="header-anchor" href="#_13-docker-swarm-从零搭建生产可用的高可用容器集群" aria-label="Permalink to “13-Docker-Swarm-从零搭建生产可用的高可用容器集群”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>当单机 Docker 不能满足可用性或扩展性要求时，集群化部署成为必然。Docker Swarm 是 Docker 官方提供的一种轻量编排方案，适合从单机容器部署平滑过渡到多节点高可用集群。</p><p>本篇文章讲清 Swarm 的核心概念、基本搭建流程、生产实践与常见注意事项。</p><h2 id="_1-swarm-是什么" tabindex="-1">1. Swarm 是什么？ <a class="header-anchor" href="#_1-swarm-是什么" aria-label="Permalink to “1. Swarm 是什么？”">​</a></h2><p>Docker Swarm 是一种集群模式，通过管理节点和工作节点，把多台主机组织成一个统一的集群。它支持：</p><ul><li>服务副本；</li><li>负载均衡；</li><li>滚动更新；</li><li>服务发现；</li><li>Overlay 网络。</li></ul><p>与 Kubernetes 相比，Swarm 更轻量、入门更快捷，适合中小规模业务或容器编排的起步阶段。</p><h2 id="_2-swarm-基本概念" tabindex="-1">2. Swarm 基本概念 <a class="header-anchor" href="#_2-swarm-基本概念" aria-label="Permalink to “2. Swarm 基本概念”">​</a></h2><ul><li>管理节点（Manager）：负责集群控制面、调度和状态管理；</li><li>工作节点（Worker）：负责运行容器服务实例；</li><li>服务（Service）：定义要运行的容器镜像、副本数、网络等；</li><li>任务（Task）：服务的具体实例。</li></ul><h2 id="_3-从零搭建-swarm" tabindex="-1">3. 从零搭建 Swarm <a class="header-anchor" href="#_3-从零搭建-swarm" aria-label="Permalink to “3. 从零搭建 Swarm”">​</a></h2><h3 id="初始化-swarm" tabindex="-1">初始化 Swarm <a class="header-anchor" href="#初始化-swarm" aria-label="Permalink to “初始化 Swarm”">​</a></h3><p>在第一台主机上执行：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swarm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --advertise-addr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MANAGER-I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="加入工作节点" tabindex="-1">加入工作节点 <a class="header-anchor" href="#加入工作节点" aria-label="Permalink to “加入工作节点”">​</a></h3><p>在其他主机上执行：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swarm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">WORKER-TOKE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">N</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MANAGER-I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:2377</span></span></code></pre></div><h3 id="查看节点状态" tabindex="-1">查看节点状态 <a class="header-anchor" href="#查看节点状态" aria-label="Permalink to “查看节点状态”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span></span></code></pre></div><h2 id="_4-部署服务" tabindex="-1">4. 部署服务 <a class="header-anchor" href="#_4-部署服务" aria-label="Permalink to “4. 部署服务”">​</a></h2><p>使用 <code>docker service create</code> 创建服务：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --replicas</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80:80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx:latest</span></span></code></pre></div><p>这会在集群中启动 3 个容器副本，并启用内部负载均衡。</p><h2 id="_5-生产实践建议" tabindex="-1">5. 生产实践建议 <a class="header-anchor" href="#_5-生产实践建议" aria-label="Permalink to “5. 生产实践建议”">​</a></h2><h3 id="_5-1-节点角色规划" tabindex="-1">5.1 节点角色规划 <a class="header-anchor" href="#_5-1-节点角色规划" aria-label="Permalink to “5.1 节点角色规划”">​</a></h3><ul><li>生产环境最好至少 3 个管理节点；</li><li>工作节点与管理节点分离；</li><li>使用专用节点运行持久化服务或高 IO 服务。</li></ul><h3 id="_5-2-网络与存储" tabindex="-1">5.2 网络与存储 <a class="header-anchor" href="#_5-2-网络与存储" aria-label="Permalink to “5.2 网络与存储”">​</a></h3><ul><li>使用 Overlay 网络实现跨节点通信；</li><li>对持久化数据使用共享存储或外部卷插件；</li><li>避免把本地绑定卷作为生产级存储。</li></ul><h3 id="_5-3-健康检查与更新策略" tabindex="-1">5.3 健康检查与更新策略 <a class="header-anchor" href="#_5-3-健康检查与更新策略" aria-label="Permalink to “5.3 健康检查与更新策略”">​</a></h3><ul><li>使用 <code>--update-parallelism</code> 和 <code>--update-delay</code> 进行滚动更新；</li><li>结合 <code>HEALTHCHECK</code> 确保仅健康实例对外提供服务；</li><li>设置服务重启策略。</li></ul><h3 id="_5-4-监控与告警" tabindex="-1">5.4 监控与告警 <a class="header-anchor" href="#_5-4-监控与告警" aria-label="Permalink to “5.4 监控与告警”">​</a></h3><ul><li>监控节点资源、服务状态、任务重启；</li><li>关注 Overlay 网络、存储延迟、容器重启频率。</li></ul><h2 id="_6-什么时候选择-swarm" tabindex="-1">6. 什么时候选择 Swarm <a class="header-anchor" href="#_6-什么时候选择-swarm" aria-label="Permalink to “6. 什么时候选择 Swarm”">​</a></h2><p>适合：</p><ul><li>需要快速搭建多节点集群；</li><li>业务规模适中；</li><li>团队希望先打好集群基础再考虑更复杂编排平台。</li></ul><p>不适合：</p><ul><li>需要复杂自定义调度；</li><li>追求云原生生态的深度集成；</li><li>需要大规模、多租户、多集群管理。</li></ul><h2 id="_7-常见误区" tabindex="-1">7. 常见误区 <a class="header-anchor" href="#_7-常见误区" aria-label="Permalink to “7. 常见误区”">​</a></h2><ul><li>认为 Swarm 是“生产就能用所有场景”。它适合轻量级场景，但不是万能；</li><li>认为加入节点后就万事大吉。集群运维、升级、备份和存储仍然需要设计；</li><li>认为 Swarm 不需要监控。它同样需要监控节点、网络和服务状态。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>Docker Swarm 是从单机容器走向高可用集群的实用路径。它的优势是上手快、运维简洁，但要真正生产可用，仍需规划节点、网络、存储和监控。对于希望稳步过渡到集群化的团队，Swarm 是一个值得尝试的选择。</p>',41)])])}const g=a(r,[["render",h]]);export{o as __pageData,g as default};
